    @Stable
    internal actual class MutablePermissionState(
        actual override val permission: Permission,
        private val onPermissionResult: (Boolean) -> Unit,
    ) : PermissionState {
        actual constructor(
            permission: Permission,
        ) : this(permission, {})
    
        actual override var status: PermissionStatus by mutableStateOf(PermissionStatus.Denied(false))
    
        private val permissionDelegate: PermissionHelper = getIOSPermission(permission)
    
        init {
            refreshPermissionStatus()
        }
    
        actual override fun launchPermissionRequest() {
            permissionDelegate.launchPermissionRequest(
                onPermissionResult = { isGranted: Boolean ->
                    onPermissionResult(isGranted)
                    // Update status on the main thread
                    updateStatus { refreshPermissionStatus() }
                }
            )
        }
    
        actual override fun openAppSettings() {
            val settingsUrl = NSURL.URLWithString(UIApplicationOpenSettingsURLString) ?: return
            UIApplication.sharedApplication.openURL(settingsUrl)
        }
    
        internal actual fun refreshPermissionStatus() {
            permissionDelegate.getPermissionStatus { status: PermissionStatus ->
                // Ensure status update is on the main thread
                updateStatus { this.status = status }
            }
        }
    
        private fun updateStatus(action: () -> Unit) {
            // Use the main dispatcher to ensure Compose state is updated correctly
            MainScope().launch(Dispatchers.Main.immediate) {
                action()
            }
        }
    }

