 */
@OptIn(ExperimentalPermissionsApi::class)
@Composable
fun demoC(){
  Scaffold {

    val scope = rememberCoroutineScope()

    val context = LocalPlatformContext.current
    val imagePickerLauncher = rememberFilePickerLauncher(
      type = FilePickerFileType.Image,
      selectionMode = FilePickerSelectionMode.Multiple,
      onResult = { files ->
        scope.launch {
          files.firstOrNull()?.readByteArray(context)
        }
      }
    )

    val galleryImagePermission = rememberPermissionState(
      permission = Permission.Gallery,
    )


    LaunchedEffect(galleryImagePermission.status){
      // the code will execute by init and the FilePicker will be launch
      if (galleryImagePermission.status.isGranted) {
        imagePickerLauncher.launch()
      }
    }



    Column(modifier = Modifier.padding(it)) {

      Text("galleryImagePermission:"+galleryImagePermission.status.toString())

      Button(
        onClick = {
          galleryImagePermission.launchPermissionRequest()
        },
        content = { Text("Button") }
      )
    }

  }
}

